import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/REGRESSION.md","filePath":"manual-en/REGRESSION.md","lastUpdated":1785684581000}'),r={name:"manual-en/REGRESSION.md"};function i(s,e,m,d,l,_){return a(),n("div",null,[...e[0]||(e[0]=[o('<h3 id="_15-17-regression" tabindex="-1">15.17 REGRESSION <a class="header-anchor" href="#_15-17-regression" aria-label="Permalink to &quot;15.17 REGRESSION&quot;">​</a></h3><p>The <code>REGRESSION</code> procedure fits linear models to data via least-squares estimation. The procedure is appropriate for data which satisfy those assumptions typical in linear regression:</p><ul><li>The data set contains <em>n</em> observations of a dependent variable, say <em>Y_1,…,Y_n</em> , and <em>n</em> observations of one or more explanatory variables. Let <em>X</em>{11}, X_{12}_ , …, <em>X</em>{1n}_ denote the <em>n</em> observations of the first explanatory variable; <em>X</em>{21}_ ,…,<em>X</em>{2n}_ denote the <em>n</em> observations of the second explanatory variable; <em>X</em>{k1}_ ,…,<em>X</em>{kn}_ denote the <em>n</em> observations of the <em>k</em> th explanatory variable.</li><li>The dependent variable <em>Y</em> has the following relationship to the explanatory variables: <em>Y_i = b_0 + b_1 X</em>{1i} + ... + b_k X_{ki} + Z_i_ where <em>b_0, b_1, …, b_k</em> are unknown coefficients, and <em>Z_1,…,Z_n</em> are independent, normally distributed <em>noise</em> terms with mean zero and common variance. The noise, or <em>error</em> terms are unobserved. This relationship is called the <em>linear model</em>.</li></ul><p>The <code>REGRESSION</code> procedure estimates the coefficients <em>b_0,…,b_k</em> and produces output relevant to inferences for the linear model.</p><table tabindex="0"><thead><tr><th>• Syntax</th><th></th><th>Syntax definition.</th></tr></thead><tbody><tr><td>• Examples</td><td></td><td>Using the REGRESSION procedure.</td></tr></tbody></table>',5)])])}const c=t(r,[["render",i]]);export{p as __pageData,c as default};
